#include <stdio.h>
#include <stdlib.h>
int main() {
    int size = 10;
    int *arr = (int*)malloc(size * sizeof(int));
    if (arr == NULL) return 1;
    for(int j = 0; j < size; j++) {
        arr[j] = j * 35;
    }
    for(int j = 0; j < size; j++) {
        printf("%d ", arr[j]);
    }
    printf("\n");
    free(arr);
    return 0;
}
